addedToArea.action:
var w = Math.round(this.info.width/Tile.SIZE)-2; var h = Math.round(this.info.height/Tile.SIZE)-2; width = w; height = h;
var tx = this.tile_x+1; var ty = this.tile_y-h; var setTiles = this.info.xml.get("setTiles") != "false";
for(y in 0...h){if(setTiles) for(x in 0...w) if(area.emptyTile(tx+x, ty+y)) setBack(tx+x, ty+y, "empty"); setTile(tx-1, ty+y, "empty"); setTile(tx+w, ty+y, "empty");}
for(x in -1...(w+1)){setTile(tx+x, ty-1, "empty"); setTile(tx+x, ty+h, "empty");}
for(e in this.info.xml.elementsNamed("exit")){
	var x = eval(e.get("x")); var sy = e.exists("y")?eval(e.get("y")):0; h = eval(e.get("height"));
	for(y in 0...h){
		var _x = tx+x; var _y = ty+y+sy;
		area.addObject(ObjectInfo.make("station.exit", _x*Tile.SIZE, _y*Tile.SIZE));
		area.addObject(ObjectInfo.make("ship.doorh", _x*Tile.SIZE, _y*Tile.SIZE));
		if(area.hasObjectIdInTile("station.exit", _x-1, _y)){
			setTile(_x, _y, null); setTile(_x-1, _y, null); setBack(_x, _y, "no_place"); setBack(_x-1, _y, "no_place");
		} else if(area.hasObjectIdInTile("station.exit", _x+1, _y)){
			setTile(_x, _y, null); setTile(_x+1, _y, null); setBack(_x, _y, "no_place"); setBack(_x+1, _y, "no_place");
		}
	}
} for(e in this.info.xml.elementsNamed("vexit")){
	var sx = eval(e.get("x")); var y = e.exists("y")?eval(e.get("y")):0; w = eval(e.get("width"));
	for(x in 0...w){
		var _x = tx+x+sx; var _y = ty+y;
		area.addObject(ObjectInfo.make("ship.doorv", _x*Tile.SIZE, _y*Tile.SIZE));
		if(area.hasObjectIdInTile("ship.doorv", _x, _y-1)){
			setTile(_x, _y, null); setTile(_x, _y-1, null); setBack(_x, _y, "no_place"); setBack(_x, _y-1, "no_place");
		} else if(area.hasObjectIdInTile("ship.doorv", _x, _y+1)){
			setTile(_x, _y, null); setTile(_x, _y+1, null); setBack(_x, _y, "no_place"); setBack(_x, _y+1, "no_place");
		}
	}
}

removedFromArea.action:
var w = Math.round(this.info.width/Tile.SIZE)-2; var h = Math.round(this.info.height/Tile.SIZE)-2; width = w; height = h;
tx = this.tile_x+1; ty = this.tile_y-h;
for(y in -1...(h+1)) for(x in -1...(w+1)){setTile(tx+x, ty+y, null); setBack(tx+x, ty+y, null);}
for(e in this.info.xml.elementsNamed("exit")){
	var x = eval(e.get("x")); var sy = e.exists("y")?eval(e.get("y")):0; h = eval(e.get("height"));
	for(y in 0...h){
		var _x = tx+x; var _y = ty+y+sy;
		if(area.hasObjectIdInTile("station.exit", _x-1, _y)){
			setTile(_x-1, _y, "empty"); setBack(_x-1, _y, null);
		} else if(area.hasObjectIdInTile("station.exit", _x+1, _y)){
			setTile(_x+1, _y, "empty"); setBack(_x+1, _y, null);
		}
	}
} for(e in this.info.xml.elementsNamed("vexit")){
	var sx = eval(e.get("x")); var y = e.exists("y")?eval(e.get("y")):0; w = eval(e.get("width"));
	for(x in 0...w){
		var _x = tx+x+sx; var _y = ty+y;
		if(area.hasObjectIdInTile("ship.doorv", _x, _y-1)){
			setTile(_x, _y-1, "empty"); setBack(_x, _y-1, null);
		} else if(area.hasObjectIdInTile("ship.doorv", _x, _y+1)){
			setTile(_x, _y+1, "empty"); setBack(_x, _y+1, null);
		}
	}
}

data.action:
function isSpaceship(object, layer){
	return object.info.xml.get("type") == "spaceship" && object.info.xml.get("drone") != "true";
}
function getSpaceshipInDock(dock, player){
	return player.areas.get(dock.area.id.substring(0, dock.area.id.length-8)).getActionObject(dock.getInnerBounds(true), null, isSpaceship);
}

init.displayAction:
function setAnim(s, id, anim, loop){
	var t = this.getTileById(id); if(t != null) t.playAnimation(anim, loop);
	if(s != null && (t = s.getTileById(id)) != null) t.playAnimation(anim, loop);
}
function checkProgress(e){
	var s = player.areas.get(this.area.id.substring(0, this.area.id.length-8)).getStructureInTile(this.tile_x+11, this.tile_y-5);
	if(s != null && s.info.id != "station.dock") s = null;
	if(e.value >= 1 || this.queue.current == null || this.queue.current.recipe.object == null){
		var t = this.getTileById("ship"); if(t != null) t.setAnimation("hidden");
		if(s != null && (t = s.getTileById("ship")) != null) t.setAnimation("hidden");
		setAnim(s, "back", "hidden", false);
		setAnim(s, "top", "station.dock.idle.top", false);
		this.stopSFX(); if(s != null) s.stopSFX(); return;
	} var anim = "station.dock."+this.queue.current.recipe.object.id;
	setAnim(s, "back", "station.dock.build.back", true);
	setAnim(s, "top", "station.dock.build.top", true);
	if(this.sound == null) this.playSFX("build_spaceship"); if(s != null && s.sound == null) s.playSFX("build_spaceship");
	var t = this.getTileById("ship"); if(t != null){
		t.setAnimation(anim); t.setFrame(e.value*t.getMaxFrame());
	} if(s != null && (t = s.getTileById("ship")) != null){
		t.setAnimation(anim); t.setFrame(e.value*t.getMaxFrame());
	}
}
this.queue.addEventListener("progress", checkProgress);
